import type { HevyHttpError } from "./hevy-http-error.js";

export const RETRY_BACKOFF_MAX_MS = 5_000;
export const RETRY_BACKOFF_BASE_MS = 300;

export interface RetryPolicy {
	readonly maxRetries: number;
	readonly baseDelayMs: number;
	readonly maxDelayMs: number;
}

export const DEFAULT_RETRY_POLICY: RetryPolicy = {
	maxRetries: 3,
	baseDelayMs: RETRY_BACKOFF_BASE_MS,
	maxDelayMs: RETRY_BACKOFF_MAX_MS,
};

export function parseRetryAfterMs(
	value: string | null,
	now = Date.now(),
): number | undefined {
	if (!value) return undefined;
	const seconds = Number(value);
	if (Number.isFinite(seconds) && seconds >= 0) {
		return Math.round(seconds * 1_000);
	}
	const dateMillis = Date.parse(value);
	return Number.isNaN(dateMillis) ? undefined : Math.max(0, dateMillis - now);
}

/**
 * Calculate the next retry delay without performing I/O.
 *
 * Keeping this policy pure makes it independently testable and provides the
 * seam for replacing the imperative retry loop with an Effect Schedule.
 */
export function getRetryDelayMs(
	error: Pick<HevyHttpError, "status" | "headers">,
	retryAttempt: number,
	policy: RetryPolicy = DEFAULT_RETRY_POLICY,
	randomInt = (maxExclusive: number) =>
		Math.floor(Math.random() * maxExclusive),
): number {
	const exponential = Math.min(
		policy.maxDelayMs,
		policy.baseDelayMs * 2 ** Math.max(0, retryAttempt - 1),
	);
	const retryAfter =
		error.status === 429
			? parseRetryAfterMs(error.headers?.get("retry-after") ?? null)
			: undefined;
	const lowerBound =
		retryAfter === undefined ? exponential : Math.max(exponential, retryAfter);
	const jitterLimit =
		retryAfter === undefined
			? 250
			: Math.min(250, Math.max(1, retryAfter * 0.1));
	const jitter = randomInt(Math.ceil(jitterLimit));
	return lowerBound + jitter;
}

import { Duration, Effect, Schedule } from "effect";

import type { HevyHttpError } from "./hevy-http-error.js";
import {
	DEFAULT_RETRY_POLICY,
	getRetryDelayMs,
	type RetryPolicy,
} from "./retry-policy.js";

export type RetryScheduleInput = Pick<HevyHttpError, "status" | "headers">;

/**
 * Builds the Effect schedule used by retrying client programs.
 *
 * The schedule deliberately only owns retry timing and the retry count. The
 * client remains responsible for deciding whether an error is safe to retry,
 * preserving its HTTP execution metadata and observation lifecycle.
 */
export function createRetrySchedule(
	maxRetries: number,
	policy: RetryPolicy = DEFAULT_RETRY_POLICY,
	randomInt = (maxExclusive: number) =>
		Math.floor(Math.random() * maxExclusive),
): Schedule.Schedule<number, RetryScheduleInput> {
	return Schedule.recurs(Math.max(0, maxRetries)).pipe(
		Schedule.addDelay((metadata) =>
			Effect.sync(() => {
				return Duration.millis(
					getRetryDelayMs(metadata.input, metadata.attempt, policy, randomInt),
				);
			}),
		),
	);
}

import { Duration, Effect, Fiber, Schedule } from "effect";
import { TestClock } from "effect/testing";
import { describe, expect, it } from "vitest";

import { createRetrySchedule } from "./retry-schedule.js";

describe("createRetrySchedule", () => {
	it("uses the pure retry policy for each scheduled failure", async () => {
		const schedule = createRetrySchedule(2, undefined, () => 0);
		const step = await Effect.runPromise(Schedule.toStep(schedule));
		const error = {
			status: 503,
			headers: new Headers(),
		};

		const first = await Effect.runPromise(step(0, error));
		const second = await Effect.runPromise(step(0, error));

		expect(first[1]).toEqual(Duration.millis(300));
		expect(second[1]).toEqual(Duration.millis(600));
	});

	it("stops after the configured number of retries", async () => {
		const schedule = createRetrySchedule(1, undefined, () => 0);
		const step = await Effect.runPromise(Schedule.toStep(schedule));
		const error = { status: 503, headers: new Headers() };

		await Effect.runPromise(step(0, error));
		const stopped = await Effect.runPromiseExit(step(0, error));

		expect(stopped).toMatchObject({ _tag: "Failure" });
	});

	it("advances retry waits deterministically with TestClock", async () => {
		let attempts = 0;
		const error = { status: 503, headers: new Headers() };
		const task = Effect.gen(function* () {
			attempts += 1;
			if (attempts === 1) yield* Effect.fail(error);
			return "ok";
		});
		const program = Effect.gen(function* () {
			const fiber = yield* Effect.retry(
				task,
				createRetrySchedule(1, undefined, () => 0),
			).pipe(Effect.forkChild);
			yield* TestClock.adjust("300 millis");
			return yield* Fiber.join(fiber);
		});

		await expect(
			Effect.runPromise(Effect.provide(program, TestClock.layer())),
		).resolves.toBe("ok");
		expect(attempts).toBe(2);
	});
});

